function controls(){ $('parameterSections').innerHTML=groups.map(g=>'<section class="control-section"'+(g.global?' data-global="true"':'')+'><details '+(g.open?'open':'')+'><summary>'+g.title+' <span class="section-number">'+g.num+'</span></summary><div class="controls">'+g.params.map(([key,name,min,max])=>'<div class="control"><div class="control-line"><label for="r-'+key+'">'+name+'</label><input class="number-value" aria-label="'+name+': значение" id="n-'+key+'" type="number" min="'+min+'" max="'+max+'" data-param="'+key+'"></div><input type="range" id="r-'+key+'" min="'+min+'" max="'+max+'" data-param="'+key+'"></div>').join('')+'</div></details></section>').join('');
for(const el of document.querySelectorAll('[data-param],#growth')){el.addEventListener('pointerdown',()=>{checkpoint();if(el.type==='range')fastPreview=true});el.addEventListener('focus',()=>{if(el.type==='number')checkpoint()});el.addEventListener('keydown',ev=>{if(ev.key.startsWith('Arrow'))checkpoint()});el.addEventListener('input',()=>{if(el.value==='')return;const val=Math.max(+el.min,Math.min(+el.max,+el.value));setParam(el.dataset.param||'growth',val)})}}
