function renderSelection(){$('selection').innerHTML='';if(selected<0)return;const node=$('art').querySelector('[data-index="'+selected+'"]');if(!node)return;const box=node.getBBox(),matrix=node.transform.baseVal.consolidate()?.matrix;let b=box;const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.setAttribute('transform',$('art').getAttribute('transform')+' '+node.getAttribute('transform'));const s=lastLayout.scale*zoom;let x=b.x-8,y=b.y-8,w=b.width+16,h=b.height+16;group.innerHTML='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="none" stroke="#c4e999" stroke-width="'+(1/s)+'" stroke-dasharray="'+(4/s)+' '+(3/s)+'"/>'+[[x,y],[x+w,y],[x,y+h],[x+w,y+h]].map(([px,py])=>'<rect x="'+(px-3/s)+'" y="'+(py-3/s)+'" width="'+(6/s)+'" height="'+(6/s)+'" fill="#c4e999"/>').join('');$('selection').append(group)}
