function transformUI(){const el=$('transformSection');el.hidden=scope!=='letter'||selected<0;if(el.hidden)return;const o=state.letters[selected]||{};el.innerHTML='<section class="control-section"><div class="selected-heading"><strong>'+escapeHtml([...state.text][selected])+'</strong><div><h2>Буква '+(selected+1)+'</h2><span class="eyebrow">СВОБОДНАЯ ФОРМА</span></div></div><div class="sculpt-controls"><button type="button" id="sculptLetter" class="sculpt-button">✧ Лепить букву на холсте</button><label for="brushRadius">Радиус лепки <span id="brushValue">'+brushRadius+' px</span></label><input id="brushRadius" type="range" min="20" max="250" value="'+brushRadius+'"><button id="clearPins" class="text-button">Убрать ручные изгибы ('+(o.pins?.length||0)+')</button></div><div class="transform-grid">'+[['x','Позиция X',-1500,1500,0,1],['y','Позиция Y',-1500,1500,0,1],['rotation','Поворот °',-180,180,0,1],['sx','Ширина ×',.1,4,1,.05],['sy','Высота ×',.1,4,1,.05]].map(([k,label,min,max,d,step])=>'<label>'+label+'<input type="number" data-transform="'+k+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+(o[k]??d)+'"></label>').join('')+'</div><label class="check-row"><input id="lockLetter" type="checkbox" '+(o.locked?'checked':'')+'>Закрепить положение</label><button class="text-button letter-variation" id="varyLetter">⤨ Новая форма этой буквы</button><button class="text-button" id="resetLetter">↺ Вернуть настройки композиции</button><p class="letter-note">Параметры ниже меняют только выбранную букву. Остальные наследуют настройки композиции.</p></section>';el.querySelectorAll('[data-transform]').forEach(input=>{input.addEventListener('focus',checkpoint);input.addEventListener('input',()=>{if(input.value==='')return;state.letters[selected]??={};state.letters[selected][input.dataset.transform]=Math.max(+input.min,Math.min(+input.max,+input.value));schedule()})});$('sculptLetter').onclick=()=>{setMode('warp');$('artboard').scrollIntoView({behavior:'smooth',block:'center'})};$('brushRadius').oninput=()=>{brushRadius=+$('brushRadius').value;$('brushValue').textContent=brushRadius+' px';rangeFill($('brushRadius'))};rangeFill($('brushRadius'));$('clearPins').onclick=()=>{checkpoint();if(state.letters[selected])delete state.letters[selected].pins;transformUI();schedule()};$('lockLetter').onchange=()=>{checkpoint();state.letters[selected]??={};state.letters[selected].locked=$('lockLetter').checked;schedule()};$('varyLetter').onclick=()=>$('shuffle').click();$('resetLetter').onclick=()=>{checkpoint();delete state.letters[selected];syncValues();transformUI();schedule()}}
function renderPresets(){$('presets').innerHTML=E.presets.map((preset,i)=>{const p={...E.defaults,...preset.values,_preview:true},sh=E.buildGlyph(font,'R',p,2741),isWood=preset.id==='wood';return '<button class="preset '+(state.preset===preset.id?'active':'')+'" data-preset="'+preset.id+'" aria-label="Пресет '+preset.name+'" title="'+preset.note+'"><svg viewBox="-100 -420 480 560" aria-hidden="true" style="background:'+(isWood?'#e2dfd6':'#0d0f0b')+'">'+E.shapeMarkup(sh,isWood?'#39372f':'#e7e8df','preset-'+i)+'</svg><div class="preset-label">'+preset.name+'<span>0'+(i+1)+'</span></div></button>'}).join('')}
function fit(){zoom=1;pan={x:0,y:0};if(!font)return;render();const box=$('art').getBBox(),scale=lastLayout.scale;if(box.width>0&&box.height>0){zoom=Math.min(3.5,state.width*.82/(box.width*scale),state.height*.72/(box.height*scale));pan.x=-(box.x+box.width/2)*scale*zoom;pan.y=state.height*.52-lastLayout.baseline-(box.y+box.height/2)*scale*zoom}schedule()}
function catalogString(value,max=160){if(typeof value!=='string'||!value.trim()||value.length>max)throw Error('Catalog text');return value.trim()}
function catalogUrl(value){if(!value)return '';const url=new URL(value);if(url.protocol!=='https:')throw Error('Catalog URL');return url.href}
function optionalCatalogUrl(value){try{return catalogUrl(value)}catch{return ''}}
function validateCatalog(raw){
  if(!raw||raw.schema!=='arbor-font-catalog-v1'||!Array.isArray(raw.families)||raw.families.length>5000)throw Error('Catalog schema');
  const families=[];
  for(const item of raw.families){try{
    const family={slug:catalogString(item.slug,100),title:catalogString(item.title,160),authorName:typeof item.authorName==='string'?item.authorName.trim().slice(0,160):'',authorUrl:'',sourceUrl:'',pageUrl:'',license:null,styles:[]};
    for(const key of ['authorUrl','sourceUrl','pageUrl'])if(item[key])family[key]=optionalCatalogUrl(item[key]);
    if(item.license&&typeof item.license==='object')family.license={status:typeof item.license.status==='string'?item.license.status.slice(0,40):'',label:catalogString(item.license.label,100),url:catalogUrl(item.license.url)};
    if(!Array.isArray(item.styles)||item.styles.length>200)throw Error('Styles');
    for(const source of item.styles){const bytes=Number(source.bytes);if(!Number.isInteger(bytes)||bytes<1||bytes>MAX_FONT_BYTES)continue;const format=String(source.format||'').toLowerCase();if(!['ttf','otf'].includes(format))continue;family.styles.push({id:catalogString(source.id,160),label:catalogString(source.label,120),url:catalogUrl(source.url),format,bytes,isVariable:!!source.isVariable,axes:source.axes&&typeof source.axes==='object'?source.axes:{}})}
    if(family.styles.length)families.push(family);
  }catch{}}
  if(!families.length)throw Error('Empty catalog');
  return{schema:raw.schema,source:typeof raw.source==='string'?raw.source:'',families,totalFamilies:families.length,totalStyles:families.reduce((n,f)=>n+f.styles.length,0)};
}
function normalizeSearch(value){return value.toLocaleLowerCase('ru').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function setCatalogStatus(message,error=false){$('fontCatalogStatus').textContent=message;$('fontCatalogStatus').classList.toggle('error',error)}
async function loadFontCatalog(){
  $('fontSearch').disabled=true;$('retryFontCatalog').hidden=true;$('fontFamilyResults').hidden=true;$('fontStylePanel').hidden=true;setCatalogStatus('Загружаем каталог…');
  try{const response=await fetch(FONT_CATALOG_URL,{mode:'cors',credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('HTTP '+response.status);const declared=Number(response.headers.get('content-length')||0);if(declared>MAX_CATALOG_BYTES)throw Error('Catalog too large');const bytes=await response.arrayBuffer();if(bytes.byteLength>MAX_CATALOG_BYTES)throw Error('Catalog too large');fontCatalog=validateCatalog(JSON.parse(new TextDecoder().decode(bytes)));$('fontSearch').disabled=false;setCatalogStatus(fontCatalog.totalFamilies+' семейств · '+fontCatalog.totalStyles+' начертаний');renderFontFamilies();}
  catch(error){fontCatalog=null;setCatalogStatus('Каталог недоступен. Встроенные и свои шрифты продолжают работать.',true);$('retryFontCatalog').hidden=false;console.warn('Font catalog:',error)}
}
function renderFontFamilies(){if(!fontCatalog)return;const query=normalizeSearch($('fontSearch').value.trim()),matches=fontCatalog.families.filter(f=>!query||normalizeSearch(f.title+' '+f.slug+' '+f.authorName).includes(query)).slice(0,40),list=$('fontFamilyResults');list.replaceChildren();for(const family of matches){const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.dataset.catalogIndex=String(fontCatalog.families.indexOf(family));const title=document.createElement('strong');title.textContent=family.title;button.append(title);if(family.authorName){const author=document.createElement('span');author.textContent=family.authorName;button.append(author)}list.append(button)}list.hidden=false;if(!matches.length){const empty=document.createElement('p');empty.textContent='Семейства не найдены';empty.className='catalog-empty';list.append(empty)}}
function validExternalLink(url){try{return new URL(url).protocol==='https:'}catch{return false}}
function renderCatalogMeta(){const family=selectedCatalogFamily,style=family?.styles[$('fontStyleSelect').selectedIndex],meta=$('fontMeta');meta.replaceChildren();if(!family||!style)return;const add=(label,value,url)=>{if(!value)return;const row=document.createElement('div'),name=document.createElement('span');name.textContent=label;row.append(name);if(url&&validExternalLink(url)){const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=value;row.append(link)}else row.append(document.createTextNode(value));meta.append(row)};add('Автор ',family.authorName,family.authorUrl);add('Лицензия ',family.license?.label,family.license?.url);if(style.isVariable)add('Файл ','Variable · используется экземпляр по умолчанию');}
function selectCatalogFamily(index){selectedCatalogFamily=fontCatalog?.families[index]||null;if(!selectedCatalogFamily)return;const select=$('fontStyleSelect'),labelCounts=new Map();for(const style of selectedCatalogFamily.styles)labelCounts.set(style.label,(labelCounts.get(style.label)||0)+1);select.replaceChildren();for(const style of selectedCatalogFamily.styles){const option=document.createElement('option');option.value=style.id;option.textContent=style.label+(labelCounts.get(style.label)>1?' · '+Math.round(style.bytes/1024)+' КБ':'')+(style.isVariable?' · Variable':'');select.append(option)}$('fontFamilyTitle').textContent=selectedCatalogFamily.title;$('fontStylePanel').hidden=false;renderCatalogMeta()}
function selectedCatalogStyle(){return selectedCatalogFamily?.styles.find(style=>style.id===$('fontStyleSelect').value)}
function updateFontCoverage(){const output=$('fontCoverage');if(!output||!font){return}const missing=[...new Set([...state.text].filter(ch=>!/^\s$/u.test(ch)&&font.charToGlyph(ch)?.index===0))];output.textContent=missing.length?'В этом шрифте отсутствуют: '+missing.join(' '):'';output.classList.toggle('warning',!!missing.length)}
function addFontOption(key,label,category='custom'){let option=[...$('fontSelect').options].find(o=>o.value===key);if(!option){option=document.createElement('option');option.value=key;$('fontSelect').append(option)}option.textContent=label;option.dataset.source=category;return option}
function registerFont(buffer,name,key='custom-'+Date.now(),metadata=null){const parsed=opentype.parse(buffer);if(!parsed.supported||!parsed.numGlyphs)throw Error('Font');fonts[key]=parsed;fontSources[key]=buffer;fontMetadata[key]=metadata;addFontOption(key,name,metadata?.catalog?'catalog':'custom');return key}
function applyFont(key){checkpoint();state.font=key;font=fonts[key];syncValues();renderPresets();fit();updateFontCoverage()}
async function loadCatalogStyle(){const family=selectedCatalogFamily,style=selectedCatalogStyle();if(!family||!style)return;const key='catalog:'+style.id,request=++catalogRequest;catalogController?.abort();catalogController=new AbortController();$('applyCatalogFont').disabled=true;setCatalogStatus('Загружаем «'+family.title+' '+style.label+'»…');try{if(!fonts[key]){const response=await fetch(style.url,{mode:'cors',credentials:'omit',referrerPolicy:'no-referrer',signal:catalogController.signal});if(!response.ok)throw Error('HTTP '+response.status);const declared=Number(response.headers.get('content-length')||0);if(declared>MAX_FONT_BYTES)throw Error('Font too large');const buffer=await response.arrayBuffer();if(buffer.byteLength>MAX_FONT_BYTES||buffer.byteLength<100)throw Error('Font size');if(request!==catalogRequest)return;registerFont(buffer,family.title+' — '+style.label,key,{catalog:true,familySlug:family.slug,familyTitle:family.title,styleId:style.id,styleLabel:style.label,authorName:family.authorName,authorUrl:family.authorUrl,licenseLabel:family.license?.label||'',licenseUrl:family.license?.url||'',sourceUrl:family.sourceUrl,pageUrl:family.pageUrl})}if(request!==catalogRequest)return;applyFont(key);setCatalogStatus('Загружен '+family.title+' · '+style.label);toast('Шрифт применён: '+family.title+' '+style.label)}catch(error){if(error.name!=='AbortError'&&request===catalogRequest){setCatalogStatus('Не удалось загрузить шрифт. Выберите другой.',true);toast('Не удалось загрузить шрифт. Предыдущий шрифт сохранён.');console.error(error)}}finally{if(request===catalogRequest)$('applyCatalogFont').disabled=false}}
$('fontSearch').addEventListener('input',renderFontFamilies);$('retryFontCatalog').onclick=loadFontCatalog;$('fontFamilyResults').onclick=event=>{const button=event.target.closest('[data-catalog-index]');if(button)selectCatalogFamily(+button.dataset.catalogIndex)};$('fontStyleSelect').onchange=renderCatalogMeta;$('applyCatalogFont').onclick=loadCatalogStyle;
async function init(){controls();try{const loaded=await Promise.all(['italic','roman'].map(async(name)=>{const res=await fetch('assets/'+(name==='italic'?'cormorant-italic.ttf':'cormorant.ttf'));if(!res.ok)throw Error('Font load');return [name,opentype.parse(await res.arrayBuffer())]}));fonts=Object.fromEntries(loaded);font=fonts.italic;renderPresets();syncValues();fit()}catch(err){$('status').textContent='Не удалось загрузить шрифт. Обнови страницу.';console.error(err)}finally{loadFontCatalog()}}
$('textInput').addEventListener('focus',checkpoint);$('textInput').addEventListener('input',()=>{const old=[...state.text],next=[...$('textInput').value].slice(0,32);state.letters=Object.fromEntries(Object.entries(state.letters).filter(([i])=>old[i]===next[i]));state.text=next.join('');selected=-1;scope='global';syncValues();transformUI();updateFontCoverage();schedule()});$('presets').onclick=e=>{const b=e.target.closest('[data-preset]');if(!b)return;checkpoint();const p=E.presets.find(p=>p.id===b.dataset.preset);if(scope==='letter'&&selected>=0){state.letters[selected]??={};state.letters[selected].params={...E.defaults,...p.values}}else{state.params={...E.defaults,...p.values};state.preset=p.id;state.paper=p.id==='wood'?'#efede6':'#090a08';state.ink=p.id==='wood'?'#413d34':'#e8e8df'}compare=false;syncValues();fit()};$('letterTray').onclick=e=>{const b=e.target.closest('[data-letter]');if(b)selectLetter(+b.dataset.letter)};$('globalTab').onclick=()=>selectLetter(-1);$('letterTab').onclick=()=>{if(!state.text.trim())return toast('Сначала введи текст');selectLetter(selected>=0?selected:0)};$('clearSelection').onclick=()=>selectLetter(-1);$('compare').onclick=()=>{compare=!compare;syncValues();schedule()};$('shuffle').onclick=()=>{checkpoint();const seed=Math.floor(Math.random()*999999);if(scope==='letter'&&selected>=0){state.letters[selected]??={};state.letters[selected].seed=seed}else state.seed=seed;schedule();toast((scope==='letter'?'Новая форма буквы':'Новая вариация')+' · '+seed)};$('fitBtn').onclick=fit;$('zoomIn').onclick=()=>{zoom=Math.min(4,zoom*1.2);schedule()};$('zoomOut').onclick=()=>{zoom=Math.max(.25,zoom/1.2);schedule()};$('gridBtn').onclick=()=>{const on=$('artboard').classList.toggle('grid');$('gridBtn').classList.toggle('active',on);$('gridBtn').setAttribute('aria-pressed',on)};
function setMode(m){mode=m;document.body.classList.toggle('pan',m==='pan');document.body.classList.toggle('sculpting',m==='warp');$('selectTool').classList.toggle('active',m==='select');$('panTool').classList.toggle('active',m==='pan');$('warpTool').classList.toggle('active',m==='warp');schedule()}
$('selectTool').onclick=()=>setMode('select');$('panTool').onclick=()=>setMode('pan');$('warpTool').onclick=()=>{setMode('warp');if(selected<0)toast('Выбери букву и потяни её участок')};
$('undo').onclick=()=>{if(!history.length)return;future.push(snapshot());state=JSON.parse(history.pop());restore()};$('redo').onclick=()=>{if(!future.length)return;history.push(snapshot());state=JSON.parse(future.pop());restore()};function restore(){font=fonts[state.font]||fonts.italic;selected=-1;scope='global';compare=false;syncValues();transformUI();renderPresets();schedule()}
for(const id of ['ink','paper']){$(id).addEventListener('pointerdown',checkpoint);$(id).addEventListener('input',()=>{state[id]=$(id).value;syncValues();schedule()})}$('transparent').onchange=()=>{checkpoint();state.transparent=$('transparent').checked};$('invert').onclick=()=>{checkpoint();[state.ink,state.paper]=[state.paper,state.ink];syncValues();schedule()};$('aspect').onchange=()=>{checkpoint();[state.width,state.height]=$('aspect').value.split(',').map(Number);fit();syncValues()};$('fontSelect').onchange=()=>{if(fonts[$('fontSelect').value])applyFont($('fontSelect').value)};$('reset').onclick=()=>{checkpoint();if(scope==='letter'){delete state.letters[selected];transformUI()}else{state.params={...E.defaults};state.letters={};state.preset=null}syncValues();schedule();toast('Настройки сброшены')};$('exportBtn').onclick=()=>$('exportDialog').showModal();$('helpBtn').onclick=()=>$('helpDialog').showModal();
init();
let drag=null,spacePan=false;function svgPoint(ev){const p=$('canvas').createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;return p.matrixTransform($('canvas').getScreenCTM().inverse())}
function localPointer(ev,inverse){const p=$('canvas').createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;return p.matrixTransform(inverse)}
$('canvas').addEventListener('pointerdown',ev=>{
  if(!font||ev.button!==0)return;
  const pos=svgPoint(ev),node=ev.target.closest('[data-index]');
  if(mode==='pan'||spacePan){drag={type:'pan',start:pos,x:pan.x,y:pan.y};document.body.classList.add('dragging')}
  else if(mode==='warp'||ev.altKey){
    if(node)selectLetter(+node.dataset.index);
    if(selected<0)return toast('Сначала выбери букву');
    if(state.letters[selected]?.locked)return toast('Сними закрепление буквы');
    const glyph=$('art').querySelector('[data-index="'+selected+'"]'),inverse=glyph.getScreenCTM().inverse();
    drag={type:'warp',start:localPointer(ev,inverse),inverse,index:selected,changed:false};
  }else if(node){selectLetter(+node.dataset.index);if(state.letters[selected]?.locked)return;const o=state.letters[selected]||{};drag={type:'letter',start:pos,x:o.x||0,y:o.y||0,index:selected,changed:false}}
  else{selectLetter(-1);return}
  $('canvas').setPointerCapture(ev.pointerId);ev.preventDefault();
});
$('canvas').addEventListener('pointermove',ev=>{
  if(!drag)return;
  const p=drag.type==='warp'?localPointer(ev,drag.inverse):svgPoint(ev),dx=p.x-drag.start.x,dy=p.y-drag.start.y;
  if(drag.type==='pan')pan={x:drag.x+dx,y:drag.y+dy};
  else{
    if(!drag.changed&&Math.hypot(dx,dy)<2)return;
    if(!drag.changed){checkpoint();drag.changed=true;state.letters[drag.index]??={};if(drag.type==='warp'){
      const o=state.letters[drag.index];o.pins??=[];if(o.pins.length>=32){drag=null;return toast('32 изгиба на букву. Убери лишние или начни новую форму.')}
      o.pins.push({x:drag.start.x,y:drag.start.y,dx:0,dy:0,radius:brushRadius});drag.pin=o.pins.length-1;fastPreview=true;
    }}
    const o=state.letters[drag.index];
    if(drag.type==='warp'){o.pins[drag.pin].dx=Math.round(dx*10)/10;o.pins[drag.pin].dy=Math.round(dy*10)/10}
    else{o.x=Math.round((drag.x+dx/(lastLayout.scale*zoom))*10)/10;o.y=Math.round((drag.y+dy/(lastLayout.scale*zoom))*10)/10}
  }schedule();
});
function endDrag(){if(drag?.type==='letter'||drag?.type==='warp')transformUI();drag=null;fastPreview=false;document.body.classList.remove('dragging');schedule()}
$('canvas').addEventListener('pointerup',endDrag);$('canvas').addEventListener('pointercancel',endDrag);
$('canvas').addEventListener('wheel',ev=>{if(ev.ctrlKey||ev.metaKey){ev.preventDefault();zoom=Math.max(.25,Math.min(4,zoom*Math.exp(-ev.deltaY*.005)));schedule()}},{passive:false});
document.addEventListener('keydown',ev=>{if(document.body.classList.contains('photo-mode'))return;const editing=/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)||ev.target.isContentEditable;if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='z'&&!editing){ev.preventDefault();$(ev.shiftKey?'redo':'undo').click();return}if(editing)return;if(ev.key==='Escape'){selectLetter(-1);return}if(ev.key===' '&&!ev.repeat){spacePan=true;document.body.classList.add('pan');ev.preventDefault()}if(ev.key.toLowerCase()==='v')setMode('select');if(ev.key.toLowerCase()==='h')setMode('pan');if(ev.key.toLowerCase()==='w')setMode('warp');if(ev.key==='?')$('helpDialog').showModal();if(selected>=0&&ev.key.startsWith('Arrow')&&!state.letters[selected]?.locked){ev.preventDefault();if(!ev.repeat)checkpoint();let o=state.letters[selected]??={},step=ev.shiftKey?10:1;if(ev.key==='ArrowLeft')o.x=(o.x||0)-step;if(ev.key==='ArrowRight')o.x=(o.x||0)+step;if(ev.key==='ArrowUp')o.y=(o.y||0)-step;if(ev.key==='ArrowDown')o.y=(o.y||0)+step;transformUI();schedule()}});document.addEventListener('keyup',ev=>{if(ev.key===' '){spacePan=false;document.body.classList.toggle('pan',mode==='pan')}});window.addEventListener('blur',()=>{spacePan=false;endDrag();document.body.classList.toggle('pan',mode==='pan')});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function fileName(ext){return 'arbor-'+(state.text.trim().replace(/[^\p{L}\p{N}]+/gu,'-').slice(0,40)||'lettering')+'.'+ext}
function exportSvg(){const l=E.layout(font,state);const art=letteringMarkup(l,'export-');const measure=document.createElementNS('http://www.w3.org/2000/svg','svg');measure.style.cssText='position:absolute;left:-10000px;top:0;width:1600px;height:1000px;visibility:hidden;pointer-events:none';measure.innerHTML='<g>'+art+'</g>';document.body.append(measure);const box=measure.firstElementChild.getBBox();measure.remove();const scale=Math.min(state.width*.86/Math.max(1,box.width),state.height*.8/Math.max(1,box.height)),tx=state.width/2-(box.x+box.width/2)*scale,ty=state.height/2-(box.y+box.height/2)*scale;return '<svg xmlns="http://www.w3.org/2000/svg" width="'+state.width+'" height="'+state.height+'" viewBox="0 0 '+state.width+' '+state.height+'"><title>'+escapeHtml(state.text)+' — ARBOR</title>'+(state.transparent?'':'<rect width="100%" height="100%" fill="'+state.paper+'"/>')+'<g transform="translate('+tx+' '+ty+') scale('+scale+')">'+art+'</g></svg>'}
$('exportSvg').onclick=()=>{if(!font||!state.text.trim())return toast('Сначала введи текст');download(new Blob([exportSvg()],{type:'image/svg+xml;charset=utf-8'}),fileName('svg'));toast('SVG готов · все буквы в контурах');$('exportDialog').close()};
$('exportPng').onclick=async()=>{if(!font||!state.text.trim())return toast('Сначала введи текст');const button=$('exportPng');button.disabled=true;let url;try{url=URL.createObjectURL(new Blob([exportSvg()],{type:'image/svg+xml'}));const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=state.width*2;canvas.height=state.height*2;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG');download(blob,fileName('png'));$('exportDialog').close();toast('PNG готов · '+canvas.width+' × '+canvas.height)}catch(err){toast('Не удалось создать PNG. Попробуй SVG.');console.error(err)}finally{if(url)URL.revokeObjectURL(url);button.disabled=false}};
$('saveProjectMobile').onclick=()=>$('saveProject').click();
for(const el of document.querySelectorAll('.number-value'))el.addEventListener('change',()=>{el.value=params()[el.dataset.param]});
function bytesToBase64(buffer){let s='';const bytes=new Uint8Array(buffer);for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}function base64ToBytes(s){if(typeof s!=='string'||s.length>14000000)throw Error('Font too large');const raw=atob(s),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes.buffer}
$('saveProject').onclick=()=>{const metadata=fontMetadata[state.font]||null,project={format:'arbor-project',version:1,state,customFont:fontSources[state.font]?{name:$('fontSelect').selectedOptions[0].textContent,data:bytesToBase64(fontSources[state.font]),metadata}:null};download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),fileName('arbor.json'));toast('Проект сохранён вместе с настройками букв')};
$('loadProject').onclick=()=>$('projectFile').click();
function validateState(data){if(!data||typeof data.text!=='string'||[...data.text].length>32)throw Error('Text');const s={text:data.text,font:['italic','roman'].includes(data.font)?data.font:'italic',params:{...E.defaults},seed:Number.isInteger(data.seed)&&data.seed>=0&&data.seed<=999999?data.seed:2741,letters:{},ink:'#e8e8df',paper:'#171916',transparent:!!data.transparent,width:1600,height:1000,preset:E.presets.some(p=>p.id===data.preset)?data.preset:null};const copy=(source,target)=>{if(!source)return;for(const [k,,min,max] of allRanges)if(source[k]!==undefined){if(!Number.isFinite(source[k])||source[k]<min||source[k]>max)throw Error('Range');target[k]=source[k]}};copy(data.params,s.params);for(const color of ['ink','paper'])if(/^#[0-9a-f]{6}$/i.test(data[color]))s[color]=data[color];if(['1600,1000','1200,1200','1000,1400'].includes(data.width+','+data.height)){s.width=data.width;s.height=data.height}for(let i=0;i<[...s.text].length;i++){const o=data.letters?.[i];if(!o)continue;const dest={params:{}};copy(o.params,dest.params);for(const[k,min,max]of [['seed',0,999999],['x',-5000,5000],['y',-5000,5000],['rotation',-180,180],['sx',.1,4],['sy',.1,4]])if(o[k]!==undefined){if(!Number.isFinite(o[k])||o[k]<min||o[k]>max)throw Error('Transform');dest[k]=o[k]}if(o.pins!==undefined){if(!Array.isArray(o.pins)||o.pins.length>32)throw Error('Pins');dest.pins=o.pins.map(pin=>{const out={};for(const k of ['x','y','dx','dy','radius']){if(!Number.isFinite(pin[k])||Math.abs(pin[k])>5000)throw Error('Pin coordinate');out[k]=pin[k]}if(out.radius<20||out.radius>250)throw Error('Pin radius');return out})}dest.locked=!!o.locked;s.letters[i]=dest}return s}
$('projectFile').onchange=async()=>{const file=$('projectFile').files[0];if(!file)return;try{if(file.size>15000000)throw Error('Size');const data=JSON.parse(await file.text());if(data.format!=='arbor-project'||data.version!==1)throw Error('Format');const next=validateState(data.state);if(data.customFont){const metadata=data.customFont.metadata&&typeof data.customFont.metadata==='object'?data.customFont.metadata:null;next.font=registerFont(base64ToBytes(data.customFont.data),String(data.customFont.name).slice(0,80),'custom-'+Date.now(),metadata)}checkpoint();state=next;restore();fit();updateFontCoverage();toast('Проект открыт')}catch(err){toast('Не удалось открыть проект. Нужен файл .arbor.json.');console.error(err)}finally{$('projectFile').value=''}};
$('uploadFont').onclick=()=>$('fontFile').click();$('fontFile').onchange=async()=>{const file=$('fontFile').files[0];if(!file)return;try{if(file.size>MAX_FONT_BYTES)throw Error('Size');const buffer=await file.arrayBuffer(),key=registerFont(buffer,file.name);applyFont(key);toast('Шрифт загружен. Он остаётся в этом браузере.')}catch(err){toast('Шрифт не прочитан. Попробуй другой TTF или OTF.');console.error(err)}finally{$('fontFile').value=''}};
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close()}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const schemas=Object.fromEntries(allRanges.map(([k,,min,max])=>[k,{type:'number',minimum:min,maximum:max}]));for(const tool of [{name:'read_lettering',title:'Прочитать композицию',description:'Return the current lettering text, vector growth settings, colors and per-letter transforms.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>JSON.parse(snapshot())},{name:'configure_lettering',title:'Настроить леттеринг',description:'Update the visible lettering text, organic stroke anatomy, bark, pores, dust and growth parameters. Set letterIndex to apply parameters to one letter. Does not download or publish.',inputSchema:{type:'object',properties:{text:{type:'string',maxLength:32},letterIndex:{type:'integer',minimum:0,maximum:31},parameters:{type:'object',properties:schemas,additionalProperties:false}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input!=='object')throw Error('Expected configuration');const next=JSON.parse(snapshot());if(input.text!==undefined){if(typeof input.text!=='string'||[...input.text].length>32)throw Error('Maximum 32 characters');next.text=input.text;next.letters={}}if(input.letterIndex!==undefined&&(!Number.isInteger(input.letterIndex)||input.letterIndex<0||input.letterIndex>=[...next.text].length))throw Error('Letter index out of bounds');const p=input.parameters||{};for(const[k,v]of Object.entries(p)){if(!schemas[k]||!Number.isFinite(v)||v<schemas[k].minimum||v>schemas[k].maximum)throw Error('Invalid parameter: '+k)}if(input.letterIndex!==undefined){const globalKey=Object.keys(p).find(k=>globalParams.has(k));if(globalKey)throw Error('Composition-only parameter: '+globalKey);next.letters[input.letterIndex]??={};next.letters[input.letterIndex].params={...next.letters[input.letterIndex].params,...p}}else Object.assign(next.params,p);next.preset=null;checkpoint();state=next;selectLetter(input.letterIndex??-1);syncValues();render();return {text:state.text,letterIndex:input.letterIndex??null,parameters:params()}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const section=$('parameterSections').children[+b.dataset.jump];if(section.dataset.global)selectLetter(-1);section.querySelector('details').open=true;section.scrollIntoView({behavior:'smooth',block:'start'})});

